using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Text;

namespace UI_Desktop.Store;

internal static class StoreEventHtmlBuilder
{
	private static readonly string[] NightCardDescriptions = new string[6] { "Giảm sâu cho một game hành động được chọn riêng.", "Ưu đãi nhập vai với phần trăm giảm ngẫu nhiên.", "Cơ hội gặp game chiến thuật đáng thử trong tuần.", "Một tựa game phiêu lưu đang chờ được lật mở.", "Deal vàng dành cho game nổi bật trong danh sách.", "Ô bí mật với cơ hội nhận mức ưu đãi cao nhất." };

	private static readonly string[] NightCardTeasers = new string[6] { "-65%", "-55%", "-70%", "-50%", "-60%", "-75%" };

	private static readonly string[] NightCardStyles = new string[6] { "cyan", "purple", "blue", "magenta", "gold", "red" };

	public static string BuildDocument(StoreWebHomeContext context, DesktopEventPageResponse data)
	{
		return $"<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<title>NestG Events</title>\r\n<style>\r\n{StoreWebHomeHtmlBuilder.BuildStyles()}\r\n{BuildStyles()}\r\n{BuildLuckyStyles()}\r\n</style>\r\n</head>\r\n<body>\r\n    <div class=\"event-shell\">\r\n        {StoreWebHomeHtmlBuilder.RenderSharedHeader(context, "events")}\r\n        <main class=\"event-main\">\r\n        {RenderChestEvent(data.RandomSteamGame)}\r\n        {RenderNightMarket(data.NightMarket)}\r\n    </main>\r\n    <footer class=\"event-bottom-bar\">\r\n        <button type=\"button\" data-host-action=\"openLibrary\"><span>&#8862;</span> Thư viện game</button>\r\n        <button type=\"button\" data-host-action=\"openSupportChat\"><span>&#9835;</span> Chat hỗ trợ</button>\r\n    </footer>\r\n    <div class=\"event-toast\" data-event-toast hidden></div>\r\n    <div class=\"event-modal-backdrop\" data-payment-modal hidden>\r\n        <section class=\"event-modal\" role=\"dialog\" aria-modal=\"true\">\r\n            <button class=\"event-modal__close\" type=\"button\" data-close-payment>&times;</button>\r\n            <span class=\"event-modal__eyebrow\">THANH TOÁN SỰ KIỆN</span>\r\n            <h2 data-payment-title>Chọn phương thức thanh toán</h2>\r\n            <p data-payment-copy>Bạn có thể quét QR SePay hoặc thanh toán tức thì bằng số dư ví NestG.</p>\r\n            <div class=\"event-payment-actions\">\r\n                <button type=\"button\" data-payment-method=\"sepay\"><strong>QR SePay</strong><small>Chuyển khoản ngân hàng</small></button>\r\n                <button type=\"button\" data-payment-method=\"wallet\"><strong>Ví NestG</strong><small>Thanh toán ngay</small></button>\r\n            </div>\r\n        </section>\r\n    </div>\r\n    <div class=\"event-modal-backdrop\" data-reward-modal hidden>\r\n        <section class=\"event-modal event-reward-modal\" role=\"dialog\" aria-modal=\"true\">\r\n            <span class=\"event-modal__eyebrow\">PHẦN THƯỞNG CỦA BẠN</span>\r\n            <div class=\"event-reward-image\"><img data-reward-image alt=\"\" /></div>\r\n            <h2 data-reward-name>Steam Game</h2>\r\n            <p data-reward-version></p>\r\n            <button class=\"event-confirm-button\" type=\"button\" data-confirm-reward>Xác nhận &amp; Active</button>\r\n        </section>\r\n    </div>\r\n    {RenderChestHistoryModal(data.ChestHistory)}\r\n    <div class=\"lucky-overlay\" data-lucky-overlay hidden aria-live=\"polite\" aria-label=\"Đang mở phần thưởng may mắn\">\r\n        <div class=\"lucky-stage\">\r\n            <div class=\"lucky-particles\" data-lucky-particles aria-hidden=\"true\"></div>\r\n            <div class=\"lucky-orbit\" aria-hidden=\"true\">\r\n                <span class=\"lucky-orbit__ring\"></span>\r\n                <span class=\"lucky-orbit__ring lucky-orbit__ring--inner\"></span>\r\n                <span class=\"lucky-core\" data-lucky-icon>?</span>\r\n            </div>\r\n            <span class=\"lucky-kicker\" data-lucky-kicker>THANH TOÁN THÀNH CÔNG</span>\r\n            <h2 data-lucky-title>Đang tìm vận may của bạn...</h2>\r\n            <p data-lucky-copy>Phần thưởng đang được mở khóa</p>\r\n            <div class=\"lucky-meter\" aria-hidden=\"true\"><i></i></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<script>\r\n{BuildScript()}\r\n</script>\r\n</body>\r\n</html>";
	}

	private static string RenderPendingActions(IReadOnlyList<DesktopEventPendingActionResponse> actions)
	{
		if (actions.Count == 0)
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder("<section class=\"pending-actions\">\r\n    <div><strong>Bạn có phần thưởng đang chờ</strong><span>Hoàn tất bước mở thẻ hoặc xác nhận game vừa nhận.</span></div>\r\n    <div class=\"pending-actions__buttons\">");
		foreach (DesktopEventPendingActionResponse action in actions)
		{
			string value = ((action.Type == "chest_reward") ? "revealChestEventReward" : "revealNightMarketOffer");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(105, 3, stringBuilder2);
			handler.AppendLiteral("        <button type=\"button\" data-pending-action=\"");
			handler.AppendFormatted(value);
			handler.AppendLiteral("\" data-opening-id=\"");
			handler.AppendFormatted(action.ReferenceId, "D");
			handler.AppendLiteral("\">\r\n            ");
			handler.AppendFormatted(Encode(action.Title));
			handler.AppendLiteral("\r\n        </button>");
			stringBuilder2.Append(ref handler);
		}
		stringBuilder.Append("</div></section>");
		return stringBuilder.ToString();
	}

	private static string RenderChestHistoryModal(IReadOnlyList<DesktopChestHistoryItemResponse> history)
	{
		int value = history.Count((DesktopChestHistoryItemResponse item) => item.Status == "confirmed");
		int value2 = history.Count((DesktopChestHistoryItemResponse item) => item.CanReveal);
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopChestHistoryItemResponse item in history)
		{
			string value3 = NormalizeStyleKey(item.TierCode);
			string value4 = (item.CanReveal ? "waiting" : "confirmed");
			string value5 = (string.IsNullOrWhiteSpace(item.Reward.GameName) ? "G" : item.Reward.GameName.Substring(0, 1).ToUpperInvariant());
			string value6 = (string.IsNullOrWhiteSpace(item.Reward.ImageUrl) ? ("<span>" + Encode(value5) + "</span>") : $"<img src=\"{Encode(item.Reward.ImageUrl)}\" alt=\"{Encode(item.Reward.GameName)}\" />");
			string value7 = (item.CanReveal ? $"<button class=\"chest-history-item__action\" type=\"button\"\r\n        data-pending-action=\"revealChestEventReward\"\r\n        data-opening-id=\"{item.OpeningId:D}\">\r\n    {Encode((item.Status == "reward_ready") ? "Mở phần thưởng" : "Xem & xác nhận")}\r\n</button>" : "<button class=\"chest-history-item__action chest-history-item__action--library\"\r\n        type=\"button\" data-host-action=\"openLibrary\">Đến thư viện</button>");
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(622, 11, stringBuilder2);
			handler.AppendLiteral("<article class=\"chest-history-item tier-");
			handler.AppendFormatted(value3);
			handler.AppendLiteral("\">\r\n    <div class=\"chest-history-item__art\">");
			handler.AppendFormatted(value6);
			handler.AppendLiteral("</div>\r\n    <div class=\"chest-history-item__body\">\r\n        <div class=\"chest-history-item__topline\">\r\n            <span class=\"chest-history-tier\">");
			handler.AppendFormatted(Encode(item.TierName));
			handler.AppendLiteral("</span>\r\n            <span class=\"chest-history-status status-");
			handler.AppendFormatted(value4);
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Encode(item.StatusText));
			handler.AppendLiteral("</span>\r\n        </div>\r\n        <h3>");
			handler.AppendFormatted(Encode(item.Reward.GameName));
			handler.AppendLiteral("</h3>\r\n        <p>");
			handler.AppendFormatted(Encode(item.Reward.VersionName));
			handler.AppendLiteral("</p>\r\n        <div class=\"chest-history-item__meta\">\r\n            <span><i>&#9716;</i> ");
			handler.AppendFormatted(Encode(FormatHistoryTime(item.OpenedAtUtc)));
			handler.AppendLiteral("</span>\r\n            <span><i>&#9670;</i> ");
			handler.AppendFormatted(Encode(item.OrderCode));
			handler.AppendLiteral("</span>\r\n        </div>\r\n    </div>\r\n    <div class=\"chest-history-item__aside\">\r\n        <strong>");
			handler.AppendFormatted(Encode(item.PriceText));
			handler.AppendLiteral("</strong>\r\n        ");
			handler.AppendFormatted(value7);
			handler.AppendLiteral("\r\n    </div>\r\n</article>");
			stringBuilder2.Append(ref handler);
		}
		if (history.Count == 0)
		{
			stringBuilder.Append("<div class=\"chest-history-empty\">\r\n    <span>&#9734;</span>\r\n    <h3>Chưa có lượt mở rương</h3>\r\n    <p>Game bạn nhận được từ Random Steam Game sẽ xuất hiện tại đây.</p>\r\n</div>");
		}
		string value8 = ((history.Count == 0) ? "Chưa có" : FormatHistoryTime(history[0].OpenedAtUtc));
		return $"<div class=\"chest-history-backdrop\" data-chest-history-modal hidden>\r\n    <section class=\"chest-history-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"chest-history-title\">\r\n        <header class=\"chest-history-header\">\r\n            <div class=\"chest-history-header__icon\">&#9734;</div>\r\n            <div>\r\n                <span>RANDOM STEAM GAME</span>\r\n                <h2 id=\"chest-history-title\">Lịch sử mở rương</h2>\r\n                <p>Theo dõi toàn bộ game và phần thưởng bạn đã nhận.</p>\r\n            </div>\r\n            <button class=\"chest-history-close\" type=\"button\" data-close-chest-history aria-label=\"Đóng\">&times;</button>\r\n        </header>\r\n        <div class=\"chest-history-summary\">\r\n            <div><small>TỔNG LƯỢT</small><strong>{history.Count}</strong><span>lượt mở gần nhất</span></div>\r\n            <div><small>ĐÃ HOÀN TẤT</small><strong>{value}</strong><span>game trong thư viện</span></div>\r\n            <div><small>ĐANG CHỜ</small><strong>{value2}</strong><span>phần thưởng cần xử lý</span></div>\r\n            <div><small>GẦN NHẤT</small><strong class=\"summary-latest\">{Encode(value8)}</strong><span>thời gian nhận game</span></div>\r\n        </div>\r\n        <div class=\"chest-history-list\">{stringBuilder}</div>\r\n    </section>\r\n</div>";
	}

	private static string FormatHistoryTime(DateTime openedAtUtc)
	{
		return ((openedAtUtc.Kind == DateTimeKind.Utc) ? openedAtUtc : DateTime.SpecifyKind(openedAtUtc, DateTimeKind.Utc)).ToLocalTime().ToString("dd/MM/yyyy · HH:mm");
	}

	private static string RenderChestEvent(DesktopChestEventResponse? chestEvent)
	{
		if (chestEvent == null)
		{
			return RenderUnavailablePanel("Random Steam Game", "Sự kiện chưa được khởi tạo trên hệ thống.");
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopChestTierResponse tier in chestEvent.Tiers)
		{
			string text = NormalizeStyleKey(tier.Code);
			string value = (string.IsNullOrWhiteSpace(tier.ArtworkPath) ? ("https://nestg-assets.local/Events/chest-" + text + ".png") : tier.ArtworkPath);
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(248, 11, stringBuilder2);
			handler.AppendLiteral("<article class=\"reward-card tier-");
			handler.AppendFormatted(text);
			handler.AppendLiteral("\" data-event-search=\"");
			handler.AppendFormatted(Encode(tier.DisplayName + " " + tier.Description));
			handler.AppendLiteral("\" title=\"");
			handler.AppendFormatted(Encode(tier.CanOpen ? $"{tier.PoolGameCount} game · vòng #{tier.CycleNumber?.ToString() ?? "—"} · còn {tier.AvailableEntryCount} lượt" : tier.UnavailableReason));
			handler.AppendLiteral("\">\r\n    <h2>");
			handler.AppendFormatted(Encode(tier.DisplayName.ToUpperInvariant()));
			handler.AppendLiteral("</h2>\r\n    <div class=\"loot-chest\"><img src=\"");
			handler.AppendFormatted(Encode(value));
			handler.AppendLiteral("\" alt=\"Rương ");
			handler.AppendFormatted(Encode(tier.DisplayName));
			handler.AppendLiteral("\" /></div>\r\n    <p>");
			handler.AppendFormatted(Encode(tier.Description));
			handler.AppendLiteral("</p>\r\n    <button type=\"button\" data-open-chest=\"");
			handler.AppendFormatted(Encode(tier.Code));
			handler.AppendLiteral("\" data-title=\"Mở rương ");
			handler.AppendFormatted(Encode(tier.DisplayName));
			handler.AppendLiteral("\" ");
			handler.AppendFormatted(Disabled(!tier.CanOpen));
			handler.AppendLiteral(">");
			handler.AppendFormatted(Encode(tier.PriceText));
			handler.AppendLiteral("</button>\r\n</article>");
			stringBuilder2.Append(ref handler);
		}
		return $"<section class=\"event-panel featured-panel\">\r\n    <div class=\"event-section-heading\">\r\n        <div><h1><span class=\"heading-icon\">&#9734;</span> SỰ KIỆN NỔI BẬT</h1><p>Tham gia ngay để nhận ưu đãi cực hấp dẫn!</p></div>\r\n        <button type=\"button\" class=\"section-link section-link--detail\" data-open-chest-history>Xem chi tiết <span>&#8594;</span></button>\r\n    </div>\r\n    <div class=\"featured-layout\">\r\n        <article class=\"festival-card\" style=\"{BackgroundImage(chestEvent.HeroArtworkPath)}\">\r\n            <div class=\"festival-copy\">\r\n                <strong class=\"festival-season\">SUMMER</strong>\r\n                <strong class=\"festival-name\">GAME FEST</strong>\r\n                <span class=\"festival-subtitle\">SĂN GAME HOT<br />NHẬN QUÀ ĐỈNH</span>\r\n            </div>\r\n            {RenderCountdown(chestEvent.EndsAtUtc, "KẾT THÚC SAU")}\r\n        </article>\r\n        <div class=\"reward-track\">{stringBuilder}</div>\r\n    </div>\r\n</section>";
	}

	private static string RenderNightMarket(DesktopNightMarketResponse? nightMarket)
	{
		if (nightMarket == null)
		{
			return RenderUnavailablePanel("Night Market", "Sự kiện chưa được khởi tạo trên hệ thống.");
		}
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopNightMarketSlotResponse item in nightMarket.Slots.OrderBy((DesktopNightMarketSlotResponse item) => item.SlotNumber))
		{
			int num = Math.Clamp(item.SlotNumber - 1, 0, NightCardStyles.Length - 1);
			string value = NightCardStyles[num];
			DesktopNightMarketOfferResponse offer = item.Offer;
			if (offer != null)
			{
				string value2 = (offer.IsPurchased ? ("<button disabled>Đã mua · " + Encode(offer.FinalPriceText) + "</button>") : $"<button type=\"button\" data-buy-offer=\"{offer.OpeningId:D}\" data-title=\"Mua {Encode(offer.GameName)}\">MUA {Encode(offer.FinalPriceText)}</button>");
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder3 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(210, 10, stringBuilder2);
				handler.AppendLiteral("<article class=\"deal-card deal-");
				handler.AppendFormatted(value);
				handler.AppendLiteral(" is-revealed\" data-event-search=\"");
				handler.AppendFormatted(Encode(offer.GameName + " " + item.CardLevelName));
				handler.AppendLiteral("\">\r\n    <strong>-");
				handler.AppendFormatted(Encode(offer.DiscountPercentText));
				handler.AppendLiteral("</strong>\r\n    <div class=\"offer-image\"><img src=\"");
				handler.AppendFormatted(Encode(offer.ImageUrl));
				handler.AppendLiteral("\" alt=\"");
				handler.AppendFormatted(Encode(offer.GameName));
				handler.AppendLiteral("\" /></div>\r\n    <h3>");
				handler.AppendFormatted(Encode(offer.GameName));
				handler.AppendLiteral("</h3>\r\n    <p>");
				handler.AppendFormatted(Encode(offer.VersionName));
				handler.AppendLiteral(" · <s>");
				handler.AppendFormatted(Encode(offer.BasePriceText));
				handler.AppendLiteral("</s></p>\r\n    ");
				handler.AppendFormatted(RenderOfferCountdown(offer.ExpiresAtUtc));
				handler.AppendLiteral("\r\n    ");
				handler.AppendFormatted(value2);
				handler.AppendLiteral("\r\n</article>");
				stringBuilder3.Append(ref handler);
			}
			else
			{
				string text = NightCardDescriptions[Math.Clamp(item.SlotNumber - 1, 0, NightCardDescriptions.Length - 1)];
				string value3 = NightCardTeasers[num];
				string value4 = ((item.RewardReady && item.OpeningId.HasValue) ? $"data-reveal-night=\"{item.OpeningId:D}\"" : $"data-open-night=\"{item.SlotNumber}\"");
				string value5 = (item.RewardReady ? "LẬT THẺ" : ((item.State == "payment_pending") ? "LƯỢT MỞ CŨ ĐANG XỬ LÝ" : "MỞ THẺ MIỄN PHÍ"));
				bool flag = item.RewardReady || item.CanOpen;
				StringBuilder stringBuilder2 = stringBuilder;
				StringBuilder stringBuilder4 = stringBuilder2;
				StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(195, 9, stringBuilder2);
				handler.AppendLiteral("<article class=\"deal-card deal-");
				handler.AppendFormatted(value);
				handler.AppendLiteral("\" data-event-search=\"");
				handler.AppendFormatted(Encode(item.CardLevelName + " " + text));
				handler.AppendLiteral("\" title=\"");
				handler.AppendFormatted(Encode(flag ? "Mở thẻ miễn phí" : item.UnavailableReason));
				handler.AppendLiteral("\">\r\n    <strong>");
				handler.AppendFormatted(value3);
				handler.AppendLiteral("</strong>\r\n    <span class=\"ticket-icon\"></span>\r\n    <p>");
				handler.AppendFormatted(Encode(text));
				handler.AppendLiteral("</p>\r\n    ");
				handler.AppendFormatted(RenderOfferCountdown(nightMarket.EndsAtUtc ?? DateTime.UtcNow));
				handler.AppendLiteral("\r\n    <button type=\"button\" ");
				handler.AppendFormatted(value4);
				handler.AppendLiteral(" ");
				handler.AppendFormatted(Disabled(!flag));
				handler.AppendLiteral(">");
				handler.AppendFormatted(value5);
				handler.AppendLiteral("</button>\r\n</article>");
				stringBuilder4.Append(ref handler);
			}
		}
		return $"<section class=\"event-panel timed-panel\">\r\n    <div class=\"event-section-heading\">\r\n        <div><h1><span class=\"heading-icon heading-icon--clock\">&#9716;</span> ƯU ĐÃI THEO THỜI GIAN</h1><p>Giảm giá sốc chỉ trong thời gian ngắn!</p></div>\r\n        <button type=\"button\" class=\"section-link\" data-host-action=\"openEvents\">Xem tất cả <span>&#8594;</span></button>\r\n    </div>\r\n    <div class=\"deal-grid\">{stringBuilder}</div>\r\n</section>";
	}

	private static string RenderCountdown(DateTime? endsAtUtc, string label)
	{
		DateTime value = endsAtUtc?.ToUniversalTime() ?? DateTime.UtcNow.AddDays(7.0);
		return $"<div class=\"featured-countdown\" data-countdown-end=\"{value:O}\">\r\n    <small>{Encode(label)}</small>\r\n    <div class=\"countdown-row\"><span><b data-days>00</b><i>NGÀY</i></span><em>:</em><span><b data-hours>00</b><i>GIỜ</i></span><em>:</em><span><b data-minutes>00</b><i>PHÚT</i></span><em>:</em><span><b data-seconds>00</b><i>GIÂY</i></span></div>\r\n</div>";
	}

	private static string RenderOfferCountdown(DateTime endsAtUtc)
	{
		return $"<div class=\"mini-countdown\" data-countdown-end=\"{endsAtUtc.ToUniversalTime():O}\"><span><b data-hours>00</b><i>GIỜ</i></span><em>:</em><span><b data-minutes>00</b><i>PHÚT</i></span><em>:</em><span><b data-seconds>00</b><i>GIÂY</i></span></div>";
	}

	private static string RenderUnavailablePanel(string title, string message)
	{
		return $"<section class=\"event-panel event-empty\"><h2>{Encode(title)}</h2><p>{Encode(message)}</p></section>";
	}

	private static string RenderStatus(string status)
	{
		return $"<span class=\"event-status event-status--{NormalizeStyleKey(status)}\">{Encode(status)}</span>";
	}

	private static string RenderReason(bool enabled, string reason)
	{
		if (!enabled && !string.IsNullOrWhiteSpace(reason))
		{
			return "<span class=\"card-reason\">" + Encode(reason) + "</span>";
		}
		return string.Empty;
	}

	private static string BackgroundImage(string path)
	{
		if (!string.IsNullOrWhiteSpace(path))
		{
			return "background-image:linear-gradient(180deg,rgba(0,8,24,.12),rgba(0,8,24,.55)),url('" + Encode(path) + "')";
		}
		return string.Empty;
	}

	private static string Disabled(bool disabled)
	{
		if (!disabled)
		{
			return string.Empty;
		}
		return "disabled";
	}

	private static string Encode(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}

	private static string NormalizeStyleKey(string? value)
	{
		string text = new string((value ?? "cyan").Where(char.IsLetterOrDigit).ToArray()).ToLowerInvariant();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		return "cyan";
	}

	private static string BuildStyles()
	{
