	private static string BuildLuckyStyles()
	{
		return ".pending-actions {\r\n    position: relative;\r\n    inset: auto;\r\n    z-index: 20;\r\n    width: 100%;\r\n    max-width: none;\r\n    justify-content: space-between;\r\n    flex-wrap: wrap;\r\n}\r\n.pending-actions > div:first-child span {\r\n    display: inline;\r\n    color: #9fb0c2;\r\n    font-size: 11px;\r\n}\r\n.pending-actions__buttons {\r\n    flex-wrap: wrap;\r\n    justify-content: flex-end;\r\n}\r\n.chest-history-backdrop {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 290;\r\n    display: grid;\r\n    place-items: center;\r\n    padding: 28px;\r\n    background:\r\n        radial-gradient(circle at 50% 10%, rgba(25, 180, 255, .13), transparent 34%),\r\n        rgba(0, 6, 14, .86);\r\n    backdrop-filter: blur(12px);\r\n    animation: chest-history-fade .22s ease both;\r\n}\r\n.chest-history-backdrop[hidden] {\r\n    display: none;\r\n}\r\nbody.is-chest-history-open {\r\n    overflow: hidden;\r\n}\r\n.chest-history-dialog {\r\n    position: relative;\r\n    width: min(1040px, 94vw);\r\n    max-height: min(790px, 88vh);\r\n    display: grid;\r\n    grid-template-rows: auto auto minmax(0, 1fr);\r\n    overflow: hidden;\r\n    border: 1px solid rgba(64, 181, 255, .3);\r\n    border-radius: 20px;\r\n    background:\r\n        linear-gradient(135deg, rgba(17, 44, 65, .28), transparent 35%),\r\n        linear-gradient(180deg, #081826, #050f1a);\r\n    box-shadow:\r\n        inset 0 1px rgba(255,255,255,.05),\r\n        0 32px 100px rgba(0,0,0,.7),\r\n        0 0 50px rgba(18,154,255,.08);\r\n    animation: chest-history-rise .32s cubic-bezier(.2,.82,.24,1) both;\r\n}\r\n.chest-history-header {\r\n    position: relative;\r\n    display: grid;\r\n    grid-template-columns: 62px minmax(0, 1fr) auto;\r\n    align-items: center;\r\n    gap: 16px;\r\n    padding: 24px 28px 19px;\r\n    border-bottom: 1px solid rgba(112, 184, 229, .12);\r\n}\r\n.chest-history-header::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    left: 28px;\r\n    right: 28px;\r\n    bottom: -1px;\r\n    height: 1px;\r\n    background: linear-gradient(90deg, #21c7ff, rgba(74,111,255,.45), transparent 72%);\r\n    box-shadow: 0 0 12px rgba(33,199,255,.36);\r\n}\r\n.chest-history-header__icon {\r\n    width: 58px;\r\n    height: 58px;\r\n    display: grid;\r\n    place-items: center;\r\n    border: 1px solid rgba(38,200,255,.55);\r\n    border-radius: 17px;\r\n    background: radial-gradient(circle at 35% 25%, rgba(255,255,255,.17), transparent 30%), rgba(22,163,224,.12);\r\n    color: #28caff;\r\n    font-size: 36px;\r\n    box-shadow: inset 0 0 24px rgba(33,198,255,.12), 0 0 24px rgba(33,198,255,.11);\r\n}\r\n.chest-history-header span {\r\n    display: block;\r\n    margin-bottom: 4px;\r\n    color: #24c7ff;\r\n    font-size: 10px;\r\n    font-weight: 900;\r\n    letter-spacing: .18em;\r\n}\r\n.chest-history-header h2 {\r\n    margin: 0;\r\n    color: #f2f8ff;\r\n    font-size: 26px;\r\n    letter-spacing: -.02em;\r\n}\r\n.chest-history-header p {\r\n    margin: 5px 0 0;\r\n    color: #91a7ba;\r\n    font-size: 12px;\r\n}\r\n.chest-history-close {\r\n    align-self: start;\r\n    width: 38px;\r\n    height: 38px;\r\n    display: grid;\r\n    place-items: center;\r\n    border: 1px solid rgba(129,168,195,.2);\r\n    border-radius: 10px;\r\n    background: rgba(255,255,255,.025);\r\n    color: #9eb1c2;\r\n    font-size: 25px;\r\n    line-height: 1;\r\n}\r\n.chest-history-close:hover {\r\n    border-color: rgba(42,198,255,.48);\r\n    color: #e9f8ff;\r\n    background: rgba(42,198,255,.08);\r\n}\r\n.chest-history-summary {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, minmax(0, 1fr));\r\n    gap: 10px;\r\n    padding: 16px 28px;\r\n    background: rgba(1,10,18,.42);\r\n}\r\n.chest-history-summary > div {\r\n    min-width: 0;\r\n    display: grid;\r\n    grid-template-columns: auto 1fr;\r\n    align-items: end;\r\n    column-gap: 9px;\r\n    padding: 12px 14px;\r\n    border: 1px solid rgba(81,151,195,.15);\r\n    border-radius: 11px;\r\n    background: linear-gradient(145deg, rgba(24,59,81,.34), rgba(7,24,36,.5));\r\n}\r\n.chest-history-summary small {\r\n    grid-column: 1 / -1;\r\n    color: #708da5;\r\n    font-size: 8px;\r\n    font-weight: 850;\r\n    letter-spacing: .14em;\r\n}\r\n.chest-history-summary strong {\r\n    color: #e9f7ff;\r\n    font-size: 24px;\r\n    line-height: 1;\r\n}\r\n.chest-history-summary strong.summary-latest {\r\n    font-size: 13px;\r\n    line-height: 1.25;\r\n}\r\n.chest-history-summary span {\r\n    overflow: hidden;\r\n    color: #7890a4;\r\n    font-size: 9px;\r\n    line-height: 1.25;\r\n    text-overflow: ellipsis;\r\n}\r\n.chest-history-list {\r\n    display: grid;\r\n    grid-auto-rows: minmax(104px, max-content);\r\n    align-content: start;\r\n    gap: 10px;\r\n    min-height: 230px;\r\n    padding: 4px 28px 26px;\r\n    overflow-y: auto;\r\n    scrollbar-color: rgba(33,198,255,.38) transparent;\r\n}\r\n.chest-history-item {\r\n    --tier: #c7d7e8;\r\n    --tier-rgb: 199,215,232;\r\n    position: relative;\r\n    min-width: 0;\r\n    min-height: 104px;\r\n    display: grid;\r\n    grid-template-columns: 116px minmax(0, 1fr) 145px;\r\n    align-items: center;\r\n    gap: 17px;\r\n    padding: 12px 14px 12px 12px;\r\n    overflow: hidden;\r\n    border: 1px solid rgba(var(--tier-rgb),.2);\r\n    border-radius: 12px;\r\n    background:\r\n        radial-gradient(circle at 10% 50%, rgba(var(--tier-rgb),.1), transparent 26%),\r\n        linear-gradient(90deg, rgba(15,35,49,.95), rgba(7,22,34,.95));\r\n    transition: border-color .2s, transform .2s, box-shadow .2s;\r\n}\r\n.chest-history-item::before {\r\n    content: \"\";\r\n    position: absolute;\r\n    left: 0;\r\n    top: 13px;\r\n    bottom: 13px;\r\n    width: 2px;\r\n    border-radius: 0 3px 3px 0;\r\n    background: var(--tier);\r\n    box-shadow: 0 0 13px rgba(var(--tier-rgb),.7);\r\n}\r\n.chest-history-item:hover {\r\n    border-color: rgba(var(--tier-rgb),.42);\r\n    box-shadow: 0 12px 28px rgba(0,0,0,.2);\r\n    transform: translateY(-1px);\r\n}\r\n.chest-history-item__art {\r\n    width: 116px;\r\n    height: 69px;\r\n    display: grid;\r\n    place-items: center;\r\n    overflow: hidden;\r\n    border: 1px solid rgba(var(--tier-rgb),.22);\r\n    border-radius: 8px;\r\n    background: radial-gradient(circle, rgba(var(--tier-rgb),.18), rgba(5,19,29,.9));\r\n    color: var(--tier);\r\n    font-size: 28px;\r\n    font-weight: 900;\r\n}\r\n.chest-history-item__art img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n}\r\n.chest-history-item__body {\r\n    min-width: 0;\r\n}\r\n.chest-history-item__topline {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    margin-bottom: 5px;\r\n}\r\n.chest-history-tier,\r\n.chest-history-status {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    min-height: 19px;\r\n    padding: 0 7px;\r\n    border-radius: 999px;\r\n    font-size: 8px;\r\n    font-weight: 850;\r\n    letter-spacing: .06em;\r\n    text-transform: uppercase;\r\n}\r\n.chest-history-tier {\r\n    border: 1px solid rgba(var(--tier-rgb),.35);\r\n    background: rgba(var(--tier-rgb),.09);\r\n    color: var(--tier);\r\n}\r\n.chest-history-status.status-confirmed {\r\n    background: rgba(45,200,130,.1);\r\n    color: #63dfa6;\r\n}\r\n.chest-history-status.status-waiting {\r\n    background: rgba(255,199,63,.11);\r\n    color: #ffd367;\r\n}\r\n.chest-history-item h3 {\r\n    overflow: hidden;\r\n    margin: 0;\r\n    color: #edf5fd;\r\n    font-size: 14px;\r\n    line-height: 1.35;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n}\r\n.chest-history-item__body > p {\r\n    overflow: hidden;\r\n    margin: 2px 0 8px;\r\n    color: #8096aa;\r\n    font-size: 10px;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n}\r\n.chest-history-item__meta {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 6px 14px;\r\n    color: #6f879b;\r\n    font-size: 9px;\r\n}\r\n.chest-history-item__meta i {\r\n    margin-right: 3px;\r\n    color: #27bfea;\r\n    font-style: normal;\r\n}\r\n.chest-history-item__aside {\r\n    min-width: 0;\r\n    display: grid;\r\n    justify-items: stretch;\r\n    gap: 9px;\r\n    padding-left: 14px;\r\n    border-left: 1px solid rgba(117,166,197,.12);\r\n}\r\n.chest-history-item__aside > strong {\r\n    color: var(--tier);\r\n    font-size: 13px;\r\n    text-align: right;\r\n}\r\n.chest-history-item__action {\r\n    min-height: 31px;\r\n    padding: 0 10px;\r\n    border: 1px solid rgba(var(--tier-rgb),.52);\r\n    border-radius: 7px;\r\n    background: rgba(var(--tier-rgb),.1);\r\n    color: var(--tier);\r\n    font-size: 9px;\r\n    font-weight: 850;\r\n    text-transform: uppercase;\r\n}\r\n.chest-history-item__action:hover:not(:disabled) {\r\n    background: rgba(var(--tier-rgb),.19);\r\n    box-shadow: 0 0 16px rgba(var(--tier-rgb),.1);\r\n}\r\n.chest-history-item__action--library {\r\n    border-color: rgba(49,190,255,.3);\r\n    background: rgba(49,190,255,.06);\r\n    color: #58ceff;\r\n}\r\n.chest-history-empty {\r\n    min-height: 270px;\r\n    display: grid;\r\n    place-items: center;\r\n    align-content: center;\r\n    padding: 30px;\r\n    text-align: center;\r\n}\r\n.chest-history-empty > span {\r\n    color: #24c8ff;\r\n    font-size: 54px;\r\n    text-shadow: 0 0 28px rgba(36,200,255,.32);\r\n}\r\n.chest-history-empty h3 {\r\n    margin: 11px 0 4px;\r\n    color: #e7f3fc;\r\n}\r\n.chest-history-empty p {\r\n    margin: 0;\r\n    color: #7f95a8;\r\n    font-size: 11px;\r\n}\r\n@keyframes chest-history-fade {\r\n    from { opacity: 0; }\r\n    to { opacity: 1; }\r\n}\r\n@keyframes chest-history-rise {\r\n    from { opacity: 0; transform: translateY(22px) scale(.975); }\r\n    to { opacity: 1; transform: none; }\r\n}\r\n.lucky-overlay {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 360;\r\n    display: grid;\r\n    place-items: center;\r\n    overflow: hidden;\r\n    padding: 24px;\r\n    background:\r\n        radial-gradient(circle at 50% 42%, rgba(34, 195, 255, .2), transparent 27%),\r\n        radial-gradient(circle at 50% 50%, rgba(120, 68, 255, .14), transparent 48%),\r\n        rgba(0, 6, 16, .92);\r\n    backdrop-filter: blur(13px);\r\n}\r\n.lucky-overlay[hidden] {\r\n    display: none;\r\n}\r\n.lucky-stage {\r\n    --lucky: #28ceff;\r\n    --lucky-rgb: 40, 206, 255;\r\n    position: relative;\r\n    width: min(560px, 92vw);\r\n    min-height: 430px;\r\n    display: grid;\r\n    justify-items: center;\r\n    align-content: center;\r\n    text-align: center;\r\n    isolation: isolate;\r\n}\r\n.lucky-overlay[data-mode=\"night_market_opening\"] .lucky-stage {\r\n    --lucky: #de63ff;\r\n    --lucky-rgb: 222, 99, 255;\r\n}\r\n.lucky-overlay[data-mode=\"night_market_purchase\"] .lucky-stage {\r\n    --lucky: #ffd34e;\r\n    --lucky-rgb: 255, 211, 78;\r\n}\r\n.lucky-orbit {\r\n    position: relative;\r\n    width: 230px;\r\n    height: 230px;\r\n    display: grid;\r\n    place-items: center;\r\n    margin-bottom: 24px;\r\n    border-radius: 50%;\r\n    filter: drop-shadow(0 0 26px rgba(var(--lucky-rgb), .28));\r\n}\r\n.lucky-orbit::before,\r\n.lucky-orbit::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    inset: 12px;\r\n    border-radius: inherit;\r\n    background: conic-gradient(from 0deg, transparent 0 8%, var(--lucky) 12%, transparent 18% 36%, var(--lucky) 43%, transparent 49% 70%, var(--lucky) 76%, transparent 84%);\r\n    -webkit-mask: radial-gradient(circle, transparent 0 69%, #000 70% 73%, transparent 74%);\r\n    mask: radial-gradient(circle, transparent 0 69%, #000 70% 73%, transparent 74%);\r\n    opacity: .8;\r\n}\r\n.lucky-orbit::after {\r\n    inset: 0;\r\n    animation: lucky-spin-reverse 2.2s linear infinite;\r\n    opacity: .38;\r\n}\r\n.lucky-orbit__ring {\r\n    position: absolute;\r\n    inset: 24px;\r\n    border: 1px solid rgba(var(--lucky-rgb), .55);\r\n    border-radius: 50%;\r\n    box-shadow: inset 0 0 24px rgba(var(--lucky-rgb), .13), 0 0 28px rgba(var(--lucky-rgb), .12);\r\n    animation: lucky-spin 1.4s linear infinite;\r\n}\r\n.lucky-orbit__ring::before,\r\n.lucky-orbit__ring::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    left: 50%;\r\n    width: 9px;\r\n    height: 9px;\r\n    border-radius: 50%;\r\n    background: var(--lucky);\r\n    box-shadow: 0 0 15px var(--lucky);\r\n    transform: translateX(-50%);\r\n}\r\n.lucky-orbit__ring::before { top: -5px; }\r\n.lucky-orbit__ring::after { bottom: -5px; }\r\n.lucky-orbit__ring--inner {\r\n    inset: 44px;\r\n    border-style: dashed;\r\n    opacity: .55;\r\n    animation-duration: 2.1s;\r\n    animation-direction: reverse;\r\n}\r\n.lucky-core {\r\n    position: relative;\r\n    z-index: 2;\r\n    width: 112px;\r\n    height: 112px;\r\n    display: grid;\r\n    place-items: center;\r\n    border: 1px solid rgba(var(--lucky-rgb), .72);\r\n    border-radius: 28px;\r\n    background: radial-gradient(circle at 38% 28%, rgba(255,255,255,.18), transparent 24%), rgba(var(--lucky-rgb), .12);\r\n    color: #f8fdff;\r\n    font-size: 52px;\r\n    font-weight: 950;\r\n    text-shadow: 0 0 18px var(--lucky);\r\n    box-shadow: inset 0 0 32px rgba(var(--lucky-rgb), .2), 0 0 42px rgba(var(--lucky-rgb), .27);\r\n    animation: lucky-core-pulse .72s ease-in-out infinite alternate;\r\n}\r\n.lucky-kicker {\r\n    color: var(--lucky);\r\n    font-size: 11px;\r\n    font-weight: 900;\r\n    letter-spacing: .22em;\r\n}\r\n.lucky-stage h2 {\r\n    margin: 9px 0 5px;\r\n    color: #f6fbff;\r\n    font-size: clamp(24px, 3vw, 36px);\r\n    text-shadow: 0 0 24px rgba(var(--lucky-rgb), .34);\r\n}\r\n.lucky-stage p {\r\n    margin: 0;\r\n    color: #99aec1;\r\n    font-size: 13px;\r\n}\r\n.lucky-meter {\r\n    width: min(320px, 72vw);\r\n    height: 5px;\r\n    margin-top: 24px;\r\n    overflow: hidden;\r\n    border-radius: 999px;\r\n    background: rgba(255,255,255,.08);\r\n}\r\n.lucky-meter i {\r\n    display: block;\r\n    width: 100%;\r\n    height: 100%;\r\n    border-radius: inherit;\r\n    background: linear-gradient(90deg, transparent, var(--lucky), #fff, var(--lucky));\r\n    box-shadow: 0 0 16px var(--lucky);\r\n    transform-origin: left;\r\n    animation: lucky-progress 2.35s cubic-bezier(.18,.72,.2,1) both;\r\n}\r\n.lucky-overlay.is-processing .lucky-meter i {\r\n    width: 34%;\r\n    animation: lucky-processing 1s ease-in-out infinite;\r\n}\r\n.lucky-particles {\r\n    position: absolute;\r\n    inset: 0;\r\n    pointer-events: none;\r\n}\r\n.lucky-particle {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 45%;\r\n    color: hsl(var(--hue), 100%, 72%);\r\n    font-size: var(--size);\r\n    opacity: 0;\r\n    text-shadow: 0 0 10px currentColor;\r\n    animation: lucky-particle-burst 1.45s ease-out var(--delay) infinite;\r\n}\r\n.lucky-overlay.is-reveal .lucky-core {\r\n    animation: lucky-reveal .58s cubic-bezier(.18,.86,.24,1.35) both;\r\n}\r\n.lucky-overlay.is-reveal .lucky-orbit {\r\n    filter: drop-shadow(0 0 48px rgba(var(--lucky-rgb), .78));\r\n}\r\n.lucky-overlay.is-reveal .lucky-meter i {\r\n    animation: none;\r\n    transform: scaleX(1);\r\n}\r\n.event-reward-modal {\r\n    animation: none;\r\n}\r\n.event-reward-modal.is-visible {\r\n    animation: event-reward-pop .5s cubic-bezier(.2,.9,.25,1.2) both;\r\n}\r\n@keyframes lucky-spin { to { transform: rotate(360deg); } }\r\n@keyframes lucky-spin-reverse { to { transform: rotate(-360deg); } }\r\n@keyframes lucky-progress { from { transform: scaleX(.03); } to { transform: scaleX(1); } }\r\n@keyframes lucky-processing {\r\n    from { transform: translateX(-130%); }\r\n    to { transform: translateX(390%); }\r\n}\r\n@keyframes lucky-core-pulse {\r\n    from { transform: scale(.9) rotate(-3deg); filter: brightness(.9); }\r\n    to { transform: scale(1.06) rotate(3deg); filter: brightness(1.3); }\r\n}\r\n@keyframes lucky-reveal {\r\n    0% { transform: scale(.72) rotate(-10deg); filter: brightness(1); }\r\n    55% { transform: scale(1.35) rotate(6deg); filter: brightness(2.1); }\r\n    100% { transform: scale(1.08); filter: brightness(1.35); }\r\n}\r\n@keyframes lucky-particle-burst {\r\n    0% { opacity: 0; transform: translate(-50%,-50%) scale(.25); }\r\n    18% { opacity: 1; }\r\n    100% { opacity: 0; transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) scale(1.15) rotate(180deg); }\r\n}\r\n@media (max-width: 720px) {\r\n    .pending-actions {\r\n        align-items: stretch;\r\n    }\r\n    .pending-actions__buttons {\r\n        width: 100%;\r\n        justify-content: flex-start;\r\n    }\r\n    .lucky-stage { min-height: 360px; }\r\n    .lucky-orbit { width: 190px; height: 190px; }\r\n    .chest-history-backdrop { padding: 10px; }\r\n    .chest-history-header { grid-template-columns: 48px minmax(0,1fr) auto; padding: 18px; }\r\n    .chest-history-header__icon { width: 46px; height: 46px; font-size: 28px; }\r\n    .chest-history-header h2 { font-size: 21px; }\r\n    .chest-history-summary { grid-template-columns: repeat(2,minmax(0,1fr)); padding: 12px 18px; }\r\n    .chest-history-list { padding: 4px 18px 20px; }\r\n    .chest-history-item { grid-template-columns: 82px minmax(0,1fr); }\r\n    .chest-history-item__art { width: 82px; height: 56px; }\r\n    .chest-history-item__aside { grid-column: 1 / -1; grid-template-columns: 1fr 145px; align-items: center; border-left: 0; padding: 0; }\r\n}\r\n@media (prefers-reduced-motion: reduce) {\r\n    .lucky-orbit::after,\r\n    .lucky-orbit__ring,\r\n    .lucky-core,\r\n    .lucky-particle,\r\n    .lucky-meter i {\r\n        animation-duration: .01ms !important;\r\n        animation-iteration-count: 1 !important;\r\n    }\r\n}";
	}

	private static string BuildScript()
	{
		return "const post = payload => window.chrome?.webview?.postMessage(payload);\r\nconst paymentModal = document.querySelector('[data-payment-modal]');\r\nconst rewardModal = document.querySelector('[data-reward-modal]');\r\nconst rewardPanel = rewardModal?.querySelector('.event-reward-modal');\r\nconst chestHistoryModal = document.querySelector('[data-chest-history-modal]');\r\nconst luckyOverlay = document.querySelector('[data-lucky-overlay]');\r\nconst luckyParticles = document.querySelector('[data-lucky-particles]');\r\nconst toast = document.querySelector('[data-event-toast]');\r\nlet pendingPayment = null;\r\nlet currentReward = null;\r\nlet toastTimer = 0;\r\nlet luckyRevealTimer = 0;\r\nlet luckyFinishTimer = 0;\r\n\r\nfunction showToast(message) {\r\n    if (!toast) return;\r\n    toast.textContent = message || '';\r\n    toast.hidden = false;\r\n    clearTimeout(toastTimer);\r\n    toastTimer = setTimeout(() => toast.hidden = true, 3200);\r\n}\r\n\r\nfunction choosePayment(payload, title) {\r\n    pendingPayment = payload;\r\n    document.querySelector('[data-payment-title]').textContent = title || 'Chọn phương thức thanh toán';\r\n    paymentModal.hidden = false;\r\n}\r\n\r\nfunction openChestHistory() {\r\n    if (!chestHistoryModal) return;\r\n    chestHistoryModal.hidden = false;\r\n    document.body.classList.add('is-chest-history-open');\r\n    chestHistoryModal.querySelector('[data-close-chest-history]')?.focus();\r\n}\r\n\r\nfunction closeChestHistory() {\r\n    if (!chestHistoryModal) return;\r\n    chestHistoryModal.hidden = true;\r\n    document.body.classList.remove('is-chest-history-open');\r\n}\r\n\r\nfunction tickCountdowns() {\r\n    document.querySelectorAll('[data-countdown-end]').forEach(root => {\r\n        const seconds = Math.max(0, Math.floor((new Date(root.dataset.countdownEnd).getTime() - Date.now()) / 1000));\r\n        const days = Math.floor(seconds / 86400);\r\n        const hours = Math.floor((seconds % 86400) / 3600);\r\n        const minutes = Math.floor((seconds % 3600) / 60);\r\n        const secs = seconds % 60;\r\n        const pad = value => String(value).padStart(2, '0');\r\n        if (root.querySelector('[data-days]')) root.querySelector('[data-days]').textContent = pad(days);\r\n        if (root.querySelector('[data-hours]')) root.querySelector('[data-hours]').textContent = pad(root.querySelector('[data-days]') ? hours : Math.floor(seconds / 3600));\r\n        if (root.querySelector('[data-minutes]')) root.querySelector('[data-minutes]').textContent = pad(minutes);\r\n        if (root.querySelector('[data-seconds]')) root.querySelector('[data-seconds]').textContent = pad(secs);\r\n    });\r\n}\r\n\r\nfunction buildLuckyParticles() {\r\n    if (!luckyParticles) return;\r\n    luckyParticles.replaceChildren();\r\n    for (let index = 0; index < 24; index += 1) {\r\n        const particle = document.createElement('span');\r\n        const angle = (Math.PI * 2 * index / 24) + (Math.random() * .18);\r\n        const distance = 105 + Math.random() * 155;\r\n        particle.className = 'lucky-particle';\r\n        particle.textContent = index % 3 === 0 ? '✦' : '•';\r\n        particle.style.setProperty('--x', `${Math.cos(angle) * distance}px`);\r\n        particle.style.setProperty('--y', `${Math.sin(angle) * distance}px`);\r\n        particle.style.setProperty('--delay', `${(index % 8) * .055}s`);\r\n        particle.style.setProperty('--size', `${8 + Math.random() * 13}px`);\r\n        particle.style.setProperty('--hue', `${185 + (index * 13) % 155}`);\r\n        luckyParticles.appendChild(particle);\r\n    }\r\n}\r\n\r\nfunction beginPaymentProcessing(rawActionType, isFreeOpening = false) {\r\n    if (!luckyOverlay) return;\r\n    const actionType = String(rawActionType || '').toLowerCase();\r\n    const mode = actionType.includes('chest')\r\n        ? 'chest_opening'\r\n        : actionType.includes('opening')\r\n            ? 'night_market_opening'\r\n            : 'night_market_purchase';\r\n    const icon = luckyOverlay.querySelector('[data-lucky-icon]');\r\n    const title = luckyOverlay.querySelector('[data-lucky-title]');\r\n    const copy = luckyOverlay.querySelector('[data-lucky-copy]');\r\n    const kicker = luckyOverlay.querySelector('[data-lucky-kicker]');\r\n\r\n    clearTimeout(luckyRevealTimer);\r\n    clearTimeout(luckyFinishTimer);\r\n    luckyOverlay.dataset.mode = mode;\r\n    luckyOverlay.classList.remove('is-reveal', 'is-running', 'is-processing');\r\n    luckyOverlay.hidden = false;\r\n    void luckyOverlay.offsetWidth;\r\n    luckyOverlay.classList.add('is-running', 'is-processing');\r\n    if (icon) icon.textContent = mode === 'chest_opening' ? '?' : mode === 'night_market_opening' ? '✦' : '✓';\r\n    if (title) {\r\n        title.textContent = mode === 'chest_opening'\r\n            ? 'Đang chuẩn bị lượt mở rương...'\r\n            : mode === 'night_market_opening'\r\n                ? 'Đang chuẩn bị thẻ may mắn...'\r\n                : 'Đang khóa ưu đãi của bạn...';\r\n    }\r\n    if (copy) {\r\n        copy.textContent = isFreeOpening\r\n            ? 'NestG đang chọn game và mức giảm dành riêng cho bạn'\r\n            : 'NestG đang xác nhận thanh toán và khóa phần thưởng';\r\n    }\r\n    if (kicker) {\r\n        kicker.textContent = isFreeOpening\r\n            ? 'MỞ THẺ MIỄN PHÍ'\r\n            : 'ĐANG XÁC NHẬN THANH TOÁN';\r\n    }\r\n    buildLuckyParticles();\r\n}\r\n\r\nfunction stopPaymentProcessing() {\r\n    if (!luckyOverlay) return;\r\n    clearTimeout(luckyRevealTimer);\r\n    clearTimeout(luckyFinishTimer);\r\n    luckyOverlay.hidden = true;\r\n    luckyOverlay.classList.remove('is-running', 'is-reveal', 'is-processing');\r\n}\r\n\r\nfunction finishLuckyEffect(actionType, referenceId) {\r\n    if (!luckyOverlay) return;\r\n    luckyOverlay.hidden = true;\r\n    luckyOverlay.classList.remove('is-running', 'is-reveal', 'is-processing');\r\n    if (actionType === 'chest_opening') {\r\n        post({ type:'revealChestEventReward', openingId:referenceId });\r\n        return;\r\n    }\r\n    if (actionType === 'night_market_opening') {\r\n        post({ type:'revealNightMarketOffer', openingId:referenceId });\r\n        return;\r\n    }\r\n    post({ type:'openEvents' });\r\n}\r\n\r\nfunction playPaymentSuccess(payload) {\r\n    const actionType = String(payload?.eventActionType || payload?.actionType || '').toLowerCase();\r\n    const referenceId = String(payload?.referenceId || '');\r\n    const isFreeOpening = payload?.isFree === true;\r\n    if (!luckyOverlay || !referenceId) {\r\n        post({ type:'openEvents' });\r\n        return;\r\n    }\r\n\r\n    clearTimeout(luckyRevealTimer);\r\n    clearTimeout(luckyFinishTimer);\r\n    const reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches === true;\r\n    const icon = luckyOverlay.querySelector('[data-lucky-icon]');\r\n    const title = luckyOverlay.querySelector('[data-lucky-title]');\r\n    const copy = luckyOverlay.querySelector('[data-lucky-copy]');\r\n    const kicker = luckyOverlay.querySelector('[data-lucky-kicker]');\r\n    const content = actionType === 'chest_opening'\r\n        ? { icon:'?', title:'Đang mở rương may mắn...', copy:'Game Steam của bạn đang được lựa chọn', done:'Vận may đã chọn xong!' }\r\n        : actionType === 'night_market_opening'\r\n            ? { icon:'✦', title:'Đang lật thẻ bí mật...', copy:'Game và mức giảm giá đang được mở khóa', done:'Ưu đãi may mắn đã xuất hiện!' }\r\n            : { icon:'✓', title:'Đang khóa ưu đãi...', copy:'Game đang được đưa vào thư viện của bạn', done:'Ưu đãi đã thuộc về bạn!' };\r\n\r\n    luckyOverlay.dataset.mode = actionType;\r\n    luckyOverlay.classList.remove('is-reveal', 'is-running', 'is-processing');\r\n    luckyOverlay.hidden = false;\r\n    void luckyOverlay.offsetWidth;\r\n    luckyOverlay.classList.add('is-running');\r\n    if (icon) icon.textContent = content.icon;\r\n    if (title) title.textContent = content.title;\r\n    if (copy) copy.textContent = content.copy;\r\n    if (kicker) {\r\n        kicker.textContent = isFreeOpening\r\n            ? 'THẺ ĐÃ ĐƯỢC MỞ MIỄN PHÍ'\r\n            : 'THANH TOÁN THÀNH CÔNG';\r\n    }\r\n    buildLuckyParticles();\r\n\r\n    luckyRevealTimer = setTimeout(() => {\r\n        luckyOverlay.classList.add('is-reveal');\r\n        if (icon) icon.textContent = actionType === 'chest_opening' ? '★' : content.icon;\r\n        if (title) title.textContent = content.done;\r\n        if (copy) {\r\n            copy.textContent = isFreeOpening\r\n                ? 'Ưu đãi đã sẵn sàng để bạn xem'\r\n                : 'Nhấn xác nhận ở bước tiếp theo để hoàn tất';\r\n        }\r\n    }, reducedMotion ? 180 : 2350);\r\n\r\n    luckyFinishTimer = setTimeout(\r\n        () => finishLuckyEffect(actionType, referenceId),\r\n        reducedMotion ? 520 : 3300);\r\n}\r\n\r\nwindow.__nestgEvent = {\r\n    showChestReward(payload) {\r\n        currentReward = payload;\r\n        document.querySelector('[data-reward-name]').textContent = payload.reward?.gameName || 'Steam Game';\r\n        document.querySelector('[data-reward-version]').textContent = payload.reward?.versionName || '';\r\n        const image = document.querySelector('[data-reward-image]');\r\n        image.src = payload.reward?.imageUrl || '';\r\n        image.alt = payload.reward?.gameName || '';\r\n        rewardPanel?.classList.remove('is-visible');\r\n        rewardModal.hidden = false;\r\n        if (rewardPanel) {\r\n            void rewardPanel.offsetWidth;\r\n            rewardPanel.classList.add('is-visible');\r\n        }\r\n    },\r\n    paymentSuccess: playPaymentSuccess,\r\n    freeOpeningSuccess(payload) {\r\n        playPaymentSuccess({ ...payload, isFree:true });\r\n    },\r\n    paymentFailed: stopPaymentProcessing,\r\n    toast: showToast\r\n};\r\n\r\ndocument.addEventListener('click', event => {\r\n    const target = event.target instanceof Element ? event.target : null;\r\n    if (!target) return;\r\n    if (target.closest('[data-open-chest-history]')) return openChestHistory();\r\n    if (target.closest('[data-close-chest-history]') || target === chestHistoryModal) {\r\n        return closeChestHistory();\r\n    }\r\n    const chest = target.closest('[data-open-chest]');\r\n    if (chest) return choosePayment({ type:'createChestEventCheckout', tierCode:chest.dataset.openChest }, chest.dataset.title);\r\n    const night = target.closest('[data-open-night]');\r\n    if (night) {\r\n        beginPaymentProcessing('night_market_opening', true);\r\n        return post({ type:'openNightMarketSlot', slotNumber:Number(night.dataset.openNight) });\r\n    }\r\n    const buy = target.closest('[data-buy-offer]');\r\n    if (buy) return choosePayment({ type:'createNightMarketPurchaseCheckout', openingId:buy.dataset.buyOffer }, buy.dataset.title);\r\n    const revealNight = target.closest('[data-reveal-night]');\r\n    if (revealNight) {\r\n        revealNight.closest('.deal-card')?.classList.add('is-opening');\r\n        return setTimeout(() => post({ type:'revealNightMarketOffer', openingId:revealNight.dataset.revealNight }), 620);\r\n    }\r\n    const pending = target.closest('[data-pending-action]');\r\n    if (pending) {\r\n        pending.disabled = true;\r\n        closeChestHistory();\r\n        return setTimeout(() => post({ type:pending.dataset.pendingAction, openingId:pending.dataset.openingId }), 260);\r\n    }\r\n    const host = target.closest('[data-host-action]');\r\n    if (host) return post({ type:host.dataset.hostAction });\r\n    if (target.closest('[data-close-payment]')) {\r\n        paymentModal.hidden = true;\r\n        pendingPayment = null;\r\n    }\r\n    const payment = target.closest('[data-payment-method]');\r\n    if (payment && pendingPayment) {\r\n        if (payment.dataset.paymentMethod === 'wallet') {\r\n            beginPaymentProcessing(pendingPayment.type);\r\n        }\r\n        paymentModal.hidden = true;\r\n        post({ ...pendingPayment, paymentMethod:payment.dataset.paymentMethod });\r\n        pendingPayment = null;\r\n    }\r\n    if (target.closest('[data-confirm-reward]') && currentReward) {\r\n        rewardModal.hidden = true;\r\n        post({ type:'confirmChestEventReward', openingId:currentReward.openingId });\r\n    }\r\n});\r\n\r\ndocument.addEventListener('keydown', event => {\r\n    if (event.key === 'Escape' && chestHistoryModal && !chestHistoryModal.hidden) {\r\n        closeChestHistory();\r\n    }\r\n});\r\n\r\ndocument.addEventListener('mousedown', event => {\r\n    const target = event.target instanceof Element ? event.target : null;\r\n    if (!target?.closest('[data-drag-region]') || target.closest('button,input,a')) return;\r\n    post({ type:'dragWindow' });\r\n});\r\n\r\ntickCountdowns();\r\nsetInterval(tickCountdowns, 1000);";
